/* non-ASCII code points whose str.lower() has ASCII letters (the rest of it written as \x01) */
static const struct { uint32_t cp; const char* s; } LOWER_ASCII[] = {
    {0x130, "i\001"},
    {0x212A, "k"},
};

/* ------------------------------------------------------------------ small helpers */

typedef struct {
  char* s;
  size_t n, cap;
} sbuf;

static void sb_putn(sbuf* b, const char* s, size_t n) {
  if (b->n + n + 1 > b->cap) {
    size_t c = b->cap ? b->cap * 2 : 64;
    while (c < b->n + n + 1) c *= 2;
    char* ns = arc_malloc(c);
    if (b->n) memcpy(ns, b->s, b->n);
    arc_free(b->s);
    b->s = ns;
    b->cap = c;
  }
  memcpy(b->s + b->n, s, n);
  b->n += n;
  b->s[b->n] = 0;
}
static void sb_putc(sbuf* b, char c) { sb_putn(b, &c, 1); }
static void sb_puts(sbuf* b, const char* s) { sb_putn(b, s, strlen(s)); }
static char* sb_done(sbuf* b) {
  if (!b->s) return arc_strdup("");
  return b->s;
}

/* one UTF-8 code point at s[*i] (an invalid byte reads as U+FFFD) */
static uint32_t u8next(const char* s, size_t* i) {
  const unsigned char* p = (const unsigned char*)s + *i;
  uint32_t c = p[0];
  int n = c < 0x80 ? 1 : (c >> 5) == 6 ? 2 : (c >> 4) == 14 ? 3 : (c >> 3) == 30 ? 4 : 0;
  if (!n) {
    (*i)++;
    return 0xFFFD;
  }
  if (n == 1) {
    (*i)++;
    return c;
  }
  uint32_t v = c & (0x7F >> n);
  for (int k = 1; k < n; ++k) {
    if ((p[k] & 0xC0) != 0x80) {
      (*i)++;
      return 0xFFFD;
    }
    v = v << 6 | (p[k] & 0x3F);
  }
  *i += (size_t)n;
  return v;
}

static int cps_of(const char* s, uint32_t** out) {
  size_t L = s ? strlen(s) : 0, i = 0;
  uint32_t* v = arc_malloc(sizeof(uint32_t) * (L + 1));
  int n = 0;
  while (i < L) v[n++] = u8next(s, &i);
  *out = v;
  return n;
}

static const char* nfkd_ascii(uint32_t cp) {
  int lo = 0, hi = (int)(sizeof NFKD_ASCII / sizeof NFKD_ASCII[0]) - 1;
  while (lo <= hi) {
    int m = (lo + hi) / 2;
    if (NFKD_ASCII[m].cp == cp) return NFKD_ASCII[m].s;
    if (NFKD_ASCII[m].cp < cp) lo = m + 1;
    else hi = m - 1;
  }
  return NULL;
}
static const char* lower_ascii(uint32_t cp) {
  for (size_t k = 0; k < sizeof LOWER_ASCII / sizeof LOWER_ASCII[0]; ++k)
    if (LOWER_ASCII[k].cp == cp) return LOWER_ASCII[k].s;
  return NULL;
}
static int cp_isupper(uint32_t cp) {
  if (cp < 0x80) return cp >= 'A' && cp <= 'Z';
  int lo = 0, hi = (int)(sizeof UPPER / sizeof UPPER[0]) - 1;
  while (lo <= hi) {
    int m = (lo + hi) / 2;
    if (cp < UPPER[m][0]) hi = m - 1;
    else if (cp > UPPER[m][1]) lo = m + 1;
    else return 1;
  }
  return 0;
}
/* str.isspace() of one code point */
static int cp_space(uint32_t c) {
  return c == ' ' || (c >= 9 && c <= 13) || (c >= 0x1C && c <= 0x1F) || c == 0x85 || c == 0xA0 || c == 0x1680 ||
         (c >= 0x2000 && c <= 0x200A) || c == 0x2028 || c == 0x2029 || c == 0x202F || c == 0x205F || c == 0x3000;
}

/* str.split() */
static int split_ws(const char* s, char*** out) {
  int cap = 8, n = 0;
  char** v = arc_malloc(sizeof(char*) * (size_t)cap);
  size_t L = s ? strlen(s) : 0, i = 0;
  while (i < L) {
    size_t j = i;
    uint32_t c = u8next(s, &j);
    if (cp_space(c)) {
      i = j;
      continue;
    }
    size_t a = i;
    while (i < L) {
      j = i;
      c = u8next(s, &j);
      if (cp_space(c)) break;
      i = j;
    }
    if (n == cap) {
      char** nv = arc_malloc(sizeof(char*) * (size_t)cap * 2);
      memcpy(nv, v, sizeof(char*) * (size_t)n);
      arc_free(v);
      v = nv;
      cap *= 2;
    }
    v[n] = arc_malloc(i - a + 1);
    memcpy(v[n], s + a, i - a);
    v[n++][i - a] = 0;
  }
  *out = v;
  return n;
}

void arc_nt_free_strs(char** s, int n) {
  if (!s) return;
  for (int i = 0; i < n; ++i) arc_free(s[i]);
  arc_free(s);
}

static char* join_ws(const char* s) {   /* ' '.join(s.split()) */
  char** w;
  int n = split_ws(s, &w);
  sbuf b = {0};
  for (int i = 0; i < n; ++i) {
    if (i) sb_putc(&b, ' ');
    sb_puts(&b, w[i]);
  }
  arc_nt_free_strs(w, n);
  return sb_done(&b);
}

/* words of an ASCII buffer made of the class chars (keep), everything else a separator */
static char* class_words(const char* s, const char* keep) {
  sbuf b = {0};
  int inw = 0;
  for (const char* p = s; *p; ++p) {
    int k = (*p >= 'a' && *p <= 'z') || (*p >= '0' && *p <= '9') || (*p && strchr(keep, *p));
    if (k) {
      if (!inw && b.n) sb_putc(&b, ' ');
      sb_putc(&b, *p);
      inw = 1;
    } else inw = 0;
  }
  return sb_done(&b);
}

/* NFKD, ascii only */
static char* fold_ascii(const char* s) {
  sbuf b = {0};
  size_t L = s ? strlen(s) : 0, i = 0;
  while (i < L) {
    uint32_t c = u8next(s, &i);
    if (c < 0x80) sb_putc(&b, (char)c);
    else {
      const char* f = nfkd_ascii(c);
      if (f) sb_puts(&b, f);
    }
  }
  return sb_done(&b);
}
/* str.lower(), with non-ASCII results written as \x01 */
static char* lower_marked(const char* s) {
  sbuf b = {0};
  size_t L = s ? strlen(s) : 0, i = 0;
  while (i < L) {
    uint32_t c = u8next(s, &i);
    if (c < 0x80) sb_putc(&b, (char)tolower((int)c));
    else {
      const char* f = lower_ascii(c);
      if (f) sb_puts(&b, f);
      else sb_putc(&b, 1);
    }
  }
  return sb_done(&b);
}

static int isword(char c) { return isalnum((unsigned char)c) || c == '_'; }

/* rescorer.norm */
char* arc_nt_norm(const char* s) {
  char* a = fold_ascii(s);
  for (char* p = a; *p; ++p) *p = (char)tolower((unsigned char)*p);
  /* re.sub("'s\b", '', s) */
  size_t L = strlen(a), o = 0;
  char* c = arc_malloc(L + 1);
  for (size_t i = 0; i < L;) {
    if (a[i] == '\'' && i + 1 < L && a[i + 1] == 's' && (i + 2 == L || !isword(a[i + 2]))) {
      i += 2;
      continue;
    }
    c[o++] = a[i++];
  }
  c[o] = 0;
  char* r = class_words(c, "");
  arc_free(a);
  arc_free(c);
  return r;
}

char* arc_nt_snorm(const char* s) {
  char* a = lower_marked(s);
  char* r = class_words(a, "");
  arc_free(a);
  return r;
}

char* arc_nt_nrm(const char* s) {
  char* a = lower_marked(s);
  char* r = class_words(a, "'");
  arc_free(a);
  return r;
}

int arc_nt_isupper0(const char* t) {
  if (!t || !*t) return 0;
  size_t i = 0;
  return cp_isupper(u8next(t, &i));
}

int arc_nt_is_cap(const char* t) {
  if (!t) return 0;
  uint32_t* c;
  int n = cps_of(t, &c), a = 0, b = n;
  while (a < b && (c[a] == '"' || c[a] == '\'' || c[a] == '(')) a++;
  while (b > a && (c[b - 1] == '"' || c[b - 1] == '\'' || c[b - 1] == '(')) b--;
  int r = a < b && cp_isupper(c[a]);
  arc_free(c);
  return r;
}

/* ------------------------------------------------------------------ metaphone (jellyfish.metaphone)
 * Port of jellyfish's metaphone (https://github.com/jamesturk/jellyfish), MIT License, Copyright (c) 2015 James Turk;
 * the licence text is in NOTICE. The end of the word reads as no character (a fallback in rescorer.py that read it as
 * '*****' differed from jellyfish on words ending in "mb", "gn", "gh"; this follows jellyfish). */
static int vowel(char c) { return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'; }
static int iey(char c) { return c == 'i' || c == 'e' || c == 'y'; }
static int oa(char c) { return c == 'o' || c == 'a'; }

char* arc_nt_metaphone(const char* in) {
  char* f = fold_ascii(in);
  for (char* p = f; *p; ++p) *p = (char)tolower((unsigned char)*p);
  const char* s = f;
  if (!strncmp(s, "kn", 2) || !strncmp(s, "gn", 2) || !strncmp(s, "pn", 2) || !strncmp(s, "wr", 2) ||
      !strncmp(s, "ae", 2))
    s++;
  int L = (int)strlen(s);
  sbuf r = {0};
  for (int i = 0; i < L; ++i) {
    char c = s[i], nx = i < L - 1 ? s[i + 1] : 0, nn = i < L - 2 ? s[i + 2] : 0;
    if (c == nx && c != 'c') continue;
    if (vowel(c)) {
      if (i == 0 || s[i - 1] == ' ') sb_putc(&r, c);
    } else if (c == 'b') {
      if (!(i != 0 && s[i - 1] == 'm') || nx) sb_putc(&r, 'b');
    } else if (c == 'c') {
      if ((nx == 'i' && nn == 'a') || nx == 'h') {
        sb_putc(&r, 'x');
        i++;
      } else if (iey(nx)) {
        sb_putc(&r, 's');
        i++;
      } else sb_putc(&r, 'k');
    } else if (c == 'd') {
      if (nx == 'g' && iey(nn)) {
        sb_putc(&r, 'j');
        i += 2;
      } else sb_putc(&r, 't');
    } else if (c == 'f' || c == 'j' || c == 'l' || c == 'm' || c == 'n' || c == 'r') {
      sb_putc(&r, c);
    } else if (c == 'g') {
      if (iey(nx)) sb_putc(&r, 'j');
      else if (nx == 'h' && !vowel(nn)) i++;
      else if (nx == 'n' && !nn) i++;
      else sb_putc(&r, 'k');
    } else if (c == 'h') {
      if (i == 0 || vowel(nx) || !vowel(s[i - 1])) sb_putc(&r, 'h');
    } else if (c == 'k') {
      if (i == 0 || s[i - 1] != 'c') sb_putc(&r, 'k');
    } else if (c == 'p') {
      if (nx == 'h') {
        sb_putc(&r, 'f');
        i++;
      } else sb_putc(&r, 'p');
    } else if (c == 'q') {
      sb_putc(&r, 'k');
    } else if (c == 's') {
      if (nx == 'h') {
        sb_putc(&r, 'x');
        i++;
      } else if (nx == 'i' && oa(nn)) {
        sb_putc(&r, 'x');
        i += 2;
      } else sb_putc(&r, 's');
    } else if (c == 't') {
      if (nx == 'i' && oa(nn)) sb_putc(&r, 'x');
      else if (nx == 'h') {
        sb_putc(&r, '0');
        i++;
      } else if (nx != 'c' || nn != 'h') sb_putc(&r, 't');
    } else if (c == 'v') {
      sb_putc(&r, 'f');
    } else if (c == 'w') {
      if (i == 0 && nx == 'h') {
        i++;
        sb_putc(&r, 'w');
      } else if (vowel(nx)) sb_putc(&r, 'w');
    } else if (c == 'x') {
      if (i == 0) sb_putc(&r, nx == 'h' || (nx == 'i' && oa(nn)) ? 'x' : 's');
      else {
        sb_putc(&r, 'k');
        sb_putc(&r, 's');
      }
    } else if (c == 'y') {
      if (vowel(nx)) sb_putc(&r, 'y');
    } else if (c == 'z') {
      sb_putc(&r, 's');
    } else if (c == ' ') {
      if (r.n && r.s[r.n - 1] != ' ') sb_putc(&r, ' ');
    }
  }
  arc_free(f);
  char* o = sb_done(&r);
  for (char* p = o; *p; ++p) *p = (char)toupper((unsigned char)*p);
  return o;
}

/* ------------------------------------------------------------------ namesim.phon */
static char* replace_all(char* s, const char* a, const char* b) {
  size_t la = strlen(a);
  if (!strstr(s, a)) return s;
  sbuf o = {0};
  for (const char* p = s; *p;) {
    if (!strncmp(p, a, la)) {
      sb_puts(&o, b);
      p += la;
    } else sb_putc(&o, *p++);
  }
  arc_free(s);
  return sb_done(&o);
}

char* arc_nt_phon(const char* t) {
  if (!t || !*t) return arc_strdup("");
  int digits = 1;
  for (const char* p = t; *p; ++p)
    if (*p < '0' || *p > '9') digits = 0;
  if (digits) return arc_strdup(t);
  static const char* R[][2] = {{"tch", "ch"}, {"sch", "sk"}, {"ph", "f"}, {"ck", "k"}, {"dg", "j"}, {"gh", ""},
                               {"qu", "kw"},  {"wr", "r"},   {"x", "ks"}, {"q", "k"},  {"z", "s"},  {"v", "f"},
                               {"sh", "x"},   {"ch", "x"},   {"th", "0"}};
  char* s = arc_strdup(t);
  for (size_t k = 0; k < sizeof R / sizeof R[0]; ++k) s = replace_all(s, R[k][0], R[k][1]);
  if (!strncmp(s, "kn", 2) || !strncmp(s, "gn", 2) || !strncmp(s, "pn", 2)) memmove(s, s + 1, strlen(s));
  size_t L = strlen(s);
  for (size_t i = 0; i < L; ++i)   /* c(?=[eiy]) -> s, then c -> k */
    if (s[i] == 'c') s[i] = iey(s[i + 1]) ? 's' : 'k';
  char head = s[0];
  sbuf r1 = {0}, r2 = {0}, r3 = {0};
  for (size_t i = 1; i < L; ++i)
    if (!vowel(s[i]) && s[i] != 'y') sb_putc(&r1, s[i]);
  for (size_t i = 0; i < r1.n; ++i)
    if (r1.s[i] != 'h') sb_putc(&r2, r1.s[i]);
  for (size_t i = 0; i < r2.n; ++i)
    if (!(r2.s[i] == 'w' && !vowel(r2.s[i + 1]))) sb_putc(&r3, r2.s[i]);
  if (!head || vowel(head) || head == 'y') head = 'a';
  sbuf o = {0};
  sb_putc(&o, head);
  if (r3.n) sb_puts(&o, r3.s);
  /* (.)\1+ -> \1 */
  size_t w = 0;
  for (size_t i = 0; i < o.n; ++i)
    if (i == 0 || o.s[i] != o.s[w - 1]) o.s[w++] = o.s[i];
  o.s[w] = 0;
  arc_free(s);
  arc_free(r1.s);
  arc_free(r2.s);
  arc_free(r3.s);
  return o.s;
}

char* arc_nt_kbmeta(const char* t) {
  char** w;
  int n = split_ws(t, &w);
  sbuf b = {0};
  for (int i = 0; i < n; ++i) {
    char* p = arc_nt_phon(w[i]);
    if (i) sb_putc(&b, ' ');
    sb_puts(&b, p);
    arc_free(p);
  }
  arc_nt_free_strs(w, n);
  return sb_done(&b);
}

/* ------------------------------------------------------------------ ratios */

static int lcs(const uint32_t* a, int la, const uint32_t* b, int lb) {
  int* prev = arc_calloc(sizeof(int) * (size_t)(lb + 1));
  int* cur = arc_calloc(sizeof(int) * (size_t)(lb + 1));
  for (int i = 0; i < la; ++i) {
    cur[0] = 0;
    for (int j = 0; j < lb; ++j)
      cur[j + 1] = a[i] == b[j] ? prev[j] + 1 : (prev[j + 1] > cur[j] ? prev[j + 1] : cur[j]);
    int* t = prev;
    prev = cur;
    cur = t;
  }
  int r = prev[lb];
  arc_free(prev);
  arc_free(cur);
  return r;
}

/* rapidfuzz fuzz.ratio / 100: normalised Indel similarity */
double arc_nt_ratio(const char* a, const char* b) {
  uint32_t *ca, *cb;
  int la = cps_of(a, &ca), lb = cps_of(b, &cb);
  double r = 1.0;
  int sum = la + lb;
  if (sum) {
    int dist = sum - 2 * lcs(ca, la, cb, lb);
    double nd = (double)dist / (double)sum;
    r = (1.0 - nd) * 100.0 / 100.0;
  }
  arc_free(ca);
  arc_free(cb);
  return r;
}

/* difflib.SequenceMatcher(None, a, b) (autojunk) on code points: total size of the matching blocks */
typedef struct {
  const uint32_t *a, *b;
  int la, lb;
  uint32_t* key;   /* b2j: sorted (element, index) pairs, popular elements removed */
  int* idx;
  int nk;
  int *j2, *nj2, *t1, *t2;
} seqm;

static int b2j_range(const seqm* m, uint32_t e, int* lo) {
  int a = 0, b = m->nk;
  while (a < b) {
    int c = (a + b) / 2;
    if (m->key[c] < e) a = c + 1;
    else b = c;
  }
  *lo = a;
  int h = a;
  while (h < m->nk && m->key[h] == e) h++;
  return h - a;
}

static int cmp_pair(const void* x, const void* y) {
  const uint64_t a = *(const uint64_t*)x, b = *(const uint64_t*)y;
  return a < b ? -1 : a > b;
}

static void longest(seqm* m, int alo, int ahi, int blo, int bhi, int* bi, int* bj, int* bs) {
  int besti = alo, bestj = blo, bestsize = 0, n1 = 0;
  for (int i = alo; i < ahi; ++i) {
    int lo, cnt = b2j_range(m, m->a[i], &lo), n2 = 0;
    for (int q = lo; q < lo + cnt; ++q) {
      int j = m->idx[q];
      if (j < blo) continue;
      if (j >= bhi) break;
      int k = (j > 0 ? m->j2[j - 1] : 0) + 1;
      m->nj2[j] = k;
      m->t2[n2++] = j;
      if (k > bestsize) {
        besti = i - k + 1;
        bestj = j - k + 1;
        bestsize = k;
      }
    }
    for (int q = 0; q < n1; ++q) m->j2[m->t1[q]] = 0;   /* j2len = newj2len */
    int *t = m->j2, *tt = m->t1;
    m->j2 = m->nj2;
    m->nj2 = t;
    m->t1 = m->t2;
    m->t2 = tt;
    n1 = n2;
  }
  for (int q = 0; q < n1; ++q) m->j2[m->t1[q]] = 0;
  while (besti > alo && bestj > blo && m->a[besti - 1] == m->b[bestj - 1]) {
    besti--;
    bestj--;
    bestsize++;
  }
  while (besti + bestsize < ahi && bestj + bestsize < bhi && m->a[besti + bestsize] == m->b[bestj + bestsize])
    bestsize++;
  *bi = besti;
  *bj = bestj;
  *bs = bestsize;
}

static int seq_matches(const uint32_t* a, int la, const uint32_t* b, int lb) {
  seqm m = {a, b, la, lb, NULL, NULL, 0, NULL, NULL, NULL, NULL};
  uint64_t* pr = arc_malloc(sizeof(uint64_t) * (size_t)(lb + 1));
  for (int j = 0; j < lb; ++j) pr[j] = (uint64_t)b[j] << 32 | (uint32_t)j;
  qsort(pr, (size_t)lb, sizeof(uint64_t), cmp_pair);
  m.key = arc_malloc(sizeof(uint32_t) * (size_t)(lb + 1));
  m.idx = arc_malloc(sizeof(int) * (size_t)(lb + 1));
  int ntest = lb / 100 + 1;
  for (int s = 0; s < lb;) {
    int e = s;
    while (e < lb && pr[e] >> 32 == pr[s] >> 32) e++;
    if (!(lb >= 200 && e - s > ntest))
      for (int q = s; q < e; ++q) {
        m.key[m.nk] = (uint32_t)(pr[q] >> 32);
        m.idx[m.nk++] = (int)(uint32_t)pr[q];
      }
    s = e;
  }
  arc_free(pr);
  m.j2 = arc_calloc(sizeof(int) * (size_t)(lb + 1));
  m.nj2 = arc_calloc(sizeof(int) * (size_t)(lb + 1));
  m.t1 = arc_malloc(sizeof(int) * (size_t)(lb + 1));
  m.t2 = arc_malloc(sizeof(int) * (size_t)(lb + 1));
  int cap = 16, nq = 1, total = 0;
  int(*q)[4] = arc_malloc(sizeof(int[4]) * (size_t)cap);
  q[0][0] = 0;
  q[0][1] = la;
  q[0][2] = 0;
  q[0][3] = lb;
  while (nq) {
    nq--;
    int alo = q[nq][0], ahi = q[nq][1], blo = q[nq][2], bhi = q[nq][3], i, j, k;
    longest(&m, alo, ahi, blo, bhi, &i, &j, &k);
    if (k) {
      total += k;
      if (nq + 2 > cap) {
        int(*nqq)[4] = arc_malloc(sizeof(int[4]) * (size_t)cap * 2);
        memcpy(nqq, q, sizeof(int[4]) * (size_t)nq);
        arc_free(q);
        q = nqq;
        cap *= 2;
      }
      if (alo < i && blo < j) {
        q[nq][0] = alo;
        q[nq][1] = i;
        q[nq][2] = blo;
        q[nq++][3] = j;
      }
      if (i + k < ahi && j + k < bhi) {
        q[nq][0] = i + k;
        q[nq][1] = ahi;
        q[nq][2] = j + k;
        q[nq++][3] = bhi;
      }
    }
  }
  arc_free(q);
  arc_free(m.key);
  arc_free(m.idx);
  arc_free(m.j2);
  arc_free(m.nj2);
  arc_free(m.t1);
  arc_free(m.t2);
  return total;
}

double arc_nt_seqratio(const char* a, const char* b) {
  uint32_t *ca, *cb;
  int la = cps_of(a, &ca), lb = cps_of(b, &cb);
  double r = la + lb ? 2.0 * seq_matches(ca, la, cb, lb) / (la + lb) : 1.0;
  arc_free(ca);
  arc_free(cb);
  return r;
}

/* ------------------------------------------------------------------ rescorer.sim */

static int u8len(const char* s) {
  int n = 0;
  for (const unsigned char* p = (const unsigned char*)s; *p; ++p) n += (*p & 0xC0) != 0x80;
  return n;
}

int arc_nt_name_forms(const arc_kbent* c, char*** out) {
  int cap = c->n_aliases + 1, n = 0;
  char** v = arc_malloc(sizeof(char*) * (size_t)cap);
  char* nm = arc_nt_norm(c->name ? c->name : "");
  int nm_sp = strchr(nm, ' ') != NULL;
  sbuf ns = {0};
  for (const char* p = nm; *p; ++p)
    if (*p != ' ') sb_putc(&ns, *p);
  char* nmc = sb_done(&ns);
  for (int k = -1; k < c->n_aliases; ++k) {
    char* f = k < 0 ? arc_strdup(nm) : arc_nt_norm(c->aliases[k]);
    int keep = f[0] && !(!strchr(f, ' ') && !strcmp(f, nmc) && nm_sp);
    for (int i = 0; i < n && keep; ++i)
      if (!strcmp(v[i], f)) keep = 0;
    if (keep) v[n++] = f;
    else arc_free(f);
  }
  arc_free(nm);
  arc_free(nmc);
  *out = v;
  return n;
}

double arc_nt_sim(const char* span, const char* const* forms, int n_forms) {
  if (!span || !*span || n_forms <= 0) return 0.0;
  char** st;
  int ns = split_ws(span, &st);
  char** sm = arc_malloc(sizeof(char*) * (size_t)(ns + 1));
  sbuf sj = {0};
  for (int i = 0; i < ns; ++i) {
    sm[i] = arc_nt_metaphone(st[i]);
    if (i) sb_putc(&sj, ' ');
    sb_puts(&sj, sm[i]);
  }
  char* smj = sb_done(&sj);
  double best = 0.0;
  for (int f = 0; f < n_forms; ++f) {
    char** tk;
    int nt = split_ws(forms[f], &tk);
    double s1 = arc_nt_ratio(span, forms[f]), s3 = 0, s4 = 0;
    sbuf tj = {0};
    for (int b = 0; b < nt; ++b) {
      char* tm = arc_nt_metaphone(tk[b]);
      if (b) sb_putc(&tj, ' ');
      sb_puts(&tj, tm);
      for (int a = 0; a < ns; ++a)
        if (u8len(st[a]) >= 3 && u8len(tk[b]) >= 3) {
          double r = arc_nt_ratio(st[a], tk[b]);
          if (r > s3) s3 = r;
          if (!strcmp(sm[a], tm)) s4 = 1.0;
        }
      arc_free(tm);
    }
    char* tmj = sb_done(&tj);
    double s5 = arc_nt_ratio(smj, tmj);
    double c[5] = {s1, 0.9 * s3, 0.85 * s4, 0.9 * s5};
    for (int k = 0; k < 4; ++k)
      if (c[k] > best) best = c[k];
    arc_free(tmj);
    arc_nt_free_strs(tk, nt);
  }
  arc_free(smj);
  arc_nt_free_strs(sm, ns);
  arc_nt_free_strs(st, ns);
  return best;
}

/* ------------------------------------------------------------------ namesim: CandTable, sim_feats */
#define DIM 4096
typedef struct {
  uint64_t bits[DIM / 64];
  float n;
} bgrow;

static void bigram(const char* s, bgrow* r) {   /* _bigram_rows for one string */
  memset(r, 0, sizeof *r);
  uint32_t* c;
  int n = cps_of(s, &c);
  uint32_t* p = arc_malloc(sizeof(uint32_t) * (size_t)(n + 2));
  p[0] = ' ';
  memcpy(p + 1, c, sizeof(uint32_t) * (size_t)n);
  p[n + 1] = ' ';
  int L = n + 2;
  if (L >= 3)
    for (int j = 0; j < L - 1; ++j) {
      uint32_t h = (uint32_t)(((uint64_t)p[j] * 131 + p[j + 1]) % DIM);
      if (!(r->bits[h / 64] >> (h % 64) & 1)) {
        r->bits[h / 64] |= 1ull << (h % 64);
        r->n += 1.0f;
      }
    }
  arc_free(c);
  arc_free(p);
}

static float dice(const bgrow* a, const bgrow* b) {
  int c = 0;
  for (int k = 0; k < DIM / 64; ++k) c += __builtin_popcountll(a->bits[k] & b->bits[k]);
  float d = a->n + b->n;
  return (2.0f * (float)c) / (d > 1.0f ? d : 1.0f);
}

static char* phon_words(const char* n) {   /* ' '.join(phon(t) for t in n.split()) */
  char** w;
  int k = split_ws(n, &w);
  sbuf b = {0};
  for (int i = 0; i < k; ++i) {
    char* p = arc_nt_phon(w[i]);
    if (i) sb_putc(&b, ' ');
    sb_puts(&b, p);
    arc_free(p);
  }
  arc_nt_free_strs(w, k);
  return sb_done(&b);
}

struct arc_nt_candtab {
  int R, ntok, maxk;
  bgrow *full, *phon, *tok;
  char** toks;
  char** tok_ph;
  int* tix;   /* [R, maxk], -1 padded */
};

static int cmp_str(const void* a, const void* b) { return strcmp(*(char* const*)a, *(char* const*)b); }

/* sorted unique tokens of length >= 3 over a set of normalised strings */
static int tok_set(char* const* ss, int n, char*** out) {
  int cap = 16, k = 0;
  char** v = arc_malloc(sizeof(char*) * (size_t)cap);
  for (int i = 0; i < n; ++i) {
    char** w;
    int nw = split_ws(ss[i], &w);
    for (int j = 0; j < nw; ++j) {
      if (u8len(w[j]) < 3) continue;
      int dup = 0;
      for (int q = 0; q < k && !dup; ++q) dup = !strcmp(v[q], w[j]);
      if (dup) continue;
      if (k == cap) {
        char** nv = arc_malloc(sizeof(char*) * (size_t)cap * 2);
        memcpy(nv, v, sizeof(char*) * (size_t)k);
        arc_free(v);
        v = nv;
        cap *= 2;
      }
      v[k++] = arc_strdup(w[j]);
    }
    arc_nt_free_strs(w, nw);
  }
  qsort(v, (size_t)k, sizeof(char*), cmp_str);
  *out = v;
  return k;
}

static int find_str(char* const* v, int n, const char* s) {   /* in a sorted array */
  int a = 0, b = n - 1;
  while (a <= b) {
    int m = (a + b) / 2, c = strcmp(v[m], s);
    if (!c) return m;
    if (c < 0) a = m + 1;
    else b = m - 1;
  }
  return -1;
}

arc_nt_candtab* arc_nt_candtab_new(const char* const* names, int R) {
  arc_nt_candtab* ct = arc_calloc(sizeof *ct);
  ct->R = R;
  char** nm = arc_malloc(sizeof(char*) * (size_t)(R + 1));
  for (int r = 0; r < R; ++r) nm[r] = arc_nt_snorm(names[r]);
  ct->full = arc_malloc(sizeof(bgrow) * (size_t)(R + 1));
  ct->phon = arc_malloc(sizeof(bgrow) * (size_t)(R + 1));
  for (int r = 0; r < R; ++r) {
    bigram(nm[r], &ct->full[r]);
    char* p = phon_words(nm[r]);
    bigram(p, &ct->phon[r]);
    arc_free(p);
  }
  ct->ntok = tok_set(nm, R, &ct->toks);
  ct->tok = arc_malloc(sizeof(bgrow) * (size_t)(ct->ntok + 1));
  ct->tok_ph = arc_malloc(sizeof(char*) * (size_t)(ct->ntok + 1));
  for (int k = 0; k < ct->ntok; ++k) {
    bigram(ct->toks[k], &ct->tok[k]);
    ct->tok_ph[k] = arc_nt_phon(ct->toks[k]);
  }
  ct->maxk = 1;
  for (int r = 0; r < R; ++r) {
    char** w;
    int nw = split_ws(nm[r], &w), c = 0;
    for (int j = 0; j < nw; ++j) c += find_str(ct->toks, ct->ntok, w[j]) >= 0;
    if (c > ct->maxk) ct->maxk = c;
    arc_nt_free_strs(w, nw);
  }
  ct->tix = arc_malloc(sizeof(int) * (size_t)(R * ct->maxk + 1));
  for (int r = 0; r < R; ++r) {
    char** w;
    int nw = split_ws(nm[r], &w), c = 0;
    for (int j = 0; j < ct->maxk; ++j) ct->tix[r * ct->maxk + j] = -1;
    for (int j = 0; j < nw; ++j) {
      int t = find_str(ct->toks, ct->ntok, w[j]);
      if (t >= 0) ct->tix[r * ct->maxk + c++] = t;
    }
    arc_nt_free_strs(w, nw);
  }
  arc_nt_free_strs(nm, R);
  return ct;
}

void arc_nt_candtab_free(arc_nt_candtab* ct) {
  if (!ct) return;
  arc_free(ct->full);
  arc_free(ct->phon);
  arc_free(ct->tok);
  arc_nt_free_strs(ct->toks, ct->ntok);
  arc_nt_free_strs(ct->tok_ph, ct->ntok);
  arc_free(ct->tix);
  arc_free(ct);
}

int arc_nt_candtab_rows(const arc_nt_candtab* ct) { return ct ? ct->R : 0; }

static float hround(float x) { return arc_round_half(x); }

void arc_nt_sim_feats(const arc_nt_candtab* ct, const char* const* spans, int S, float* out) {
  int R = ct ? ct->R : 0;
  memset(out, 0, sizeof(float) * (size_t)S * (size_t)R * 6);
  if (!S || !R) return;
  char** sp = arc_malloc(sizeof(char*) * (size_t)S);
  bgrow* F = arc_malloc(sizeof(bgrow) * (size_t)S);
  bgrow* P = arc_malloc(sizeof(bgrow) * (size_t)S);
  for (int k = 0; k < S; ++k) {
    sp[k] = arc_nt_snorm(spans[k]);
    bigram(sp[k], &F[k]);
    char* p = phon_words(sp[k]);
    bigram(p, &P[k]);
    arc_free(p);
  }
  float* stok = arc_calloc(sizeof(float) * (size_t)S * R);
  float* sptok = arc_calloc(sizeof(float) * (size_t)S * R);
  if (ct->ntok) {
    char** st;
    int nst = tok_set(sp, S, &st);
    if (nst) {
      float* Dn = arc_malloc(sizeof(float) * (size_t)nst * R);
      float* Pn = arc_malloc(sizeof(float) * (size_t)nst * R);
      float* D = arc_malloc(sizeof(float) * (size_t)ct->ntok);
      float* PE = arc_malloc(sizeof(float) * (size_t)ct->ntok);
      for (int s = 0; s < nst; ++s) {
        bgrow tr;
        bigram(st[s], &tr);
        char* ph = arc_nt_phon(st[s]);
        for (int t = 0; t < ct->ntok; ++t) {
          D[t] = dice(&tr, &ct->tok[t]);
          PE[t] = strcmp(ph, ct->tok_ph[t]) ? 0.0f : 1.0f;
        }
        arc_free(ph);
        for (int r = 0; r < R; ++r) {
          float dm = 0, pm = 0;
          for (int q = 0; q < ct->maxk; ++q) {
            int g = ct->tix[r * ct->maxk + q];
            float dv = g >= 0 ? D[g] : 0.0f, pv = g >= 0 ? PE[g] : 0.0f;
            if (q == 0 || dv > dm) dm = dv;
            if (q == 0 || pv > pm) pm = pv;
          }
          Dn[s * R + r] = dm;
          Pn[s * R + r] = pm;
        }
      }
      for (int k = 0; k < S; ++k) {
        char** w;
        int nw = split_ws(sp[k], &w), any = 0;
        for (int j = 0; j < nw; ++j) {
          int s = find_str(st, nst, w[j]);
          if (s < 0) continue;
          for (int r = 0; r < R; ++r) {
            float* a = &stok[k * R + r];
            float* b = &sptok[k * R + r];
            if (!any || Dn[s * R + r] > *a) *a = Dn[s * R + r];
            if (!any || Pn[s * R + r] > *b) *b = Pn[s * R + r];
          }
          any = 1;
        }
        arc_nt_free_strs(w, nw);
      }
      arc_free(Dn);
      arc_free(Pn);
      arc_free(D);
      arc_free(PE);
    }
    arc_nt_free_strs(st, nst);
  }
  for (int k = 0; k < S; ++k)
    for (int r = 0; r < R; ++r) {
      float sf = dice(&F[k], &ct->full[r]), sph = dice(&P[k], &ct->phon[r]);
      float a = stok[k * R + r], b = sptok[k * R + r];
      float best = sf, x;
      x = 0.9f * a;
      if (x > best) best = x;
      x = 0.85f * b;
      if (x > best) best = x;
      x = 0.9f * sph;
      if (x > best) best = x;
      float sh = (best - 0.6f) / 0.4f;
      sh = sh < 0.0f ? 0.0f : sh > 1.0f ? 1.0f : sh;
      sh = sh * sh;
      float* o = out + ((size_t)k * R + r) * 6;
      o[0] = hround(sf);
      o[1] = hround(a);
      o[2] = hround(b);
      o[3] = hround(sph);
      o[4] = hround(best);
      o[5] = hround(sh);
    }
  arc_free(stok);
  arc_free(sptok);
  arc_free(F);
  arc_free(P);
  arc_nt_free_strs(sp, S);
}

/* ------------------------------------------------------------------ policy and rescorer parameters */

static int truthy(const arc_json* j) {
  if (!j) return 0;
  if (j->type == ARC_JBOOL || j->type == ARC_JNUM) return j->num != 0;
  if (j->type == ARC_JSTR) return j->str[0] != 0;
  if (j->type == ARC_JARR || j->type == ARC_JOBJ) return j->n > 0;
  return 0;
}

static void pol_merge(const arc_json* o, arc_nt_policy* p) {
  if (!o || o->type != ARC_JOBJ) return;
  for (int i = 0; i < o->n; ++i) {
    const char* k = o->keys[i];
    const arc_json* v = &o->items[i];
    int num = v->type == ARC_JNUM;
    if (!strcmp(k, "delta")) {
      p->has_delta = num;
      p->delta = num ? v->num : 0;
    } else if (!strcmp(k, "thr")) {
      p->has_thr = num;
      p->thr = num ? v->num : 0;
    } else if (!strcmp(k, "require_heard")) p->require_heard = truthy(v);
    else if (!strcmp(k, "fuzzy_tau")) p->fuzzy_tau = truthy(v) && num ? v->num : 0;
  }
}

void arc_nt_policy_cfg(const arc_json* cfg, const char* domain, const char* word_source, arc_nt_policy* out) {
  memset(out, 0, sizeof *out);
  const char* src = word_source && (!strcmp(word_source, "builtin") || !strcmp(word_source, "external")) ? word_source
                                                                                                         : "external";
  const arc_json* npc = arc_json_get(arc_json_get(cfg, "name_policy"), src);
  pol_merge(arc_json_get(npc, "*"), out);
  pol_merge(arc_json_get(npc, domain ? domain : "unknown"), out);
}

void arc_nt_resc_params_cfg(const arc_json* cfg, const char* domain, const arc_nt_policy* pol, arc_nt_resc_params* out) {
  const arc_json* rs = arc_json_get(cfg, "rescorer");
  const arc_json* rp = arc_json_get(rs, domain ? domain : "unknown");
  if (!rp) rp = arc_json_get(rs, "unknown");
  out->A = arc_json_num(arc_json_get(rp, "A"), 0);
  out->A2 = arc_json_num(arc_json_get(rp, "A2"), 0);
  out->B = arc_json_num(arc_json_get(rp, "B"), 0);
  out->T = arc_json_num(arc_json_get(rp, "T"), 0);
  out->R = arc_json_num(arc_json_get(rp, "R"), 0);
  out->bias = arc_json_num(arc_json_get(rp, "bias"), 0);
  out->thr = arc_json_num(arc_json_get(rp, "thr"), 0.5);
  if (pol && pol->has_delta) out->bias = out->bias + pol->delta;
  if (pol && pol->has_thr) out->thr = pol->thr;
}

/* ------------------------------------------------------------------ NameRescorer */

typedef struct {
  char* group;
  char** toks;
  int n;
} team_words;

struct arc_nt_rescorer {
  int n;
  arc_nt_resc_params p;
  char*** forms;
  int* nforms;
  char** groups;
  team_words* tw;
  int ntw;
  double* rt;   /* recent (t, row), a queue from rh */
  int* rr;
  int rh, rn, rcap;
};

static int add_tok(char*** v, int* n, const char* t) {
  for (int i = 0; i < *n; ++i)
    if (!strcmp((*v)[i], t)) return 0;
  char** nv = arc_malloc(sizeof(char*) * (size_t)(*n + 1));
  if (*n) memcpy(nv, *v, sizeof(char*) * (size_t)*n);
  arc_free(*v);
  *v = nv;
  (*v)[(*n)++] = arc_strdup(t);
  return 1;
}

arc_nt_rescorer* arc_nt_rescorer_new(const arc_kbent* kb, int n, const arc_nt_resc_params* p) {
  arc_nt_rescorer* r = arc_calloc(sizeof *r);
  r->n = n;
  r->p = *p;
  r->forms = arc_calloc(sizeof(char**) * (size_t)(n + 1));
  r->nforms = arc_calloc(sizeof(int) * (size_t)(n + 1));
  r->groups = arc_calloc(sizeof(char*) * (size_t)(n + 1));
  r->tw = arc_calloc(sizeof(team_words) * (size_t)(n + 1));
  for (int i = 0; i < n; ++i) {
    r->nforms[i] = arc_nt_name_forms(&kb[i], &r->forms[i]);
    r->groups[i] = kb[i].group ? arc_strdup(kb[i].group) : NULL;
  }
  /* teams = groups of team entries; team_words[g] = their forms' words of 4+ letters */
  for (int i = 0; i < n; ++i) {
    if (!kb[i].kind || strcmp(kb[i].kind, "team") || !kb[i].group || !kb[i].group[0]) continue;
    int g = -1;
    for (int k = 0; k < r->ntw; ++k)
      if (!strcmp(r->tw[k].group, kb[i].group)) g = k;
    if (g < 0) {
      g = r->ntw++;
      r->tw[g].group = arc_strdup(kb[i].group);
    }
    for (int f = 0; f < r->nforms[i]; ++f) {
      char** w;
      int nw = split_ws(r->forms[i][f], &w);
      for (int j = 0; j < nw; ++j)
        if (u8len(w[j]) >= 4) add_tok(&r->tw[g].toks, &r->tw[g].n, w[j]);
      arc_nt_free_strs(w, nw);
    }
  }
  return r;
}

void arc_nt_rescorer_free(arc_nt_rescorer* r) {
  if (!r) return;
  for (int i = 0; i < r->n; ++i) {
    arc_nt_free_strs(r->forms[i], r->nforms[i]);
    arc_free(r->groups[i]);
  }
  for (int k = 0; k < r->ntw; ++k) {
    arc_free(r->tw[k].group);
    arc_nt_free_strs(r->tw[k].toks, r->tw[k].n);
  }
  arc_free(r->forms);
  arc_free(r->nforms);
  arc_free(r->groups);
  arc_free(r->tw);
  arc_free(r->rt);
  arc_free(r->rr);
  arc_free(r);
}

void arc_nt_rescorer_push(arc_nt_rescorer* r, double t, int row) {
  if (r->rh + r->rn == r->rcap) {
    if (r->rh) {
      memmove(r->rt, r->rt + r->rh, sizeof(double) * (size_t)r->rn);
      memmove(r->rr, r->rr + r->rh, sizeof(int) * (size_t)r->rn);
      r->rh = 0;
    }
    if (r->rn == r->rcap) {
      int c = r->rcap ? r->rcap * 2 : 16;
      double* nt = arc_malloc(sizeof(double) * (size_t)c);
      int* nr = arc_malloc(sizeof(int) * (size_t)c);
      if (r->rn) {
        memcpy(nt, r->rt, sizeof(double) * (size_t)r->rn);
        memcpy(nr, r->rr, sizeof(int) * (size_t)r->rn);
      }
      arc_free(r->rt);
      arc_free(r->rr);
      r->rt = nt;
      r->rr = nr;
      r->rcap = c;
    }
  }
  r->rt[r->rh + r->rn] = t;
  r->rr[r->rh + r->rn] = row;
  r->rn++;
}

/* numpy's logaddexp */
static double logaddexp(double x, double y) {
  if (x == y) return x + 0.693147180559945309417232121458176568;
  double t = x - y;
  if (t > 0) return x + log1p(exp(-t));
  if (t <= 0) return y + log1p(exp(t));
  return t;
}

/* numpy's pairwise summation (the add reduction of a float64 array) */
static double pw_sum(const double* a, int n) {
  if (n < 8) {
    double r = 0.;
    for (int i = 0; i < n; ++i) r += a[i];
    return r;
  }
  if (n <= 128) {
    double r[8];
    for (int k = 0; k < 8; ++k) r[k] = a[k];
    int i;
    for (i = 8; i < n - (n % 8); i += 8)
      for (int k = 0; k < 8; ++k) r[k] += a[i + k];
    double res = ((r[0] + r[1]) + (r[2] + r[3])) + ((r[4] + r[5]) + (r[6] + r[7]));
    for (; i < n; ++i) res += a[i];
    return res;
  }
  int n2 = n / 2;
  n2 -= n2 % 8;
  return pw_sum(a, n2) + pw_sum(a + n2, n - n2);
}

static double np_sum(const double* a, int n) { return n ? a[0] + pw_sum(a + 1, n - 1) : 0.0; }

/* Python's round(x, nd) */
static double pyround(double x, int nd) {
  char b[64];
  snprintf(b, sizeof b, "%.*f", nd, x);
  for (char* q = b; *q; ++q)
    if (*q == ',') *q = '.';   /* a comma-decimal locale */
  return arc_strtod(b, NULL);
}

static int count_sub(const char* s, const char* f) {   /* str.count */
  size_t lf = strlen(f);
  if (!lf) return (int)strlen(s) + 1;
  int c = 0;
  for (const char* p = strstr(s, f); p; p = strstr(p + lf, f)) c++;
  return c;
}

int arc_nt_rescorer_score(arc_nt_rescorer* r, double t_s, const float* z, int nz, const int* allowed, int na,
                          const char* span_text, const char* past_text, const char* feed_text, arc_nt_resc_out* out) {
  const arc_nt_resc_params* p = &r->p;
  while (r->rn && r->rt[r->rh] < t_s - 120) {
    r->rh++;
    r->rn--;
  }
  double* zz = arc_malloc(sizeof(double) * (size_t)(nz + 1));
  double L = 0;
  int first = 1;
  for (int i = 0; i < nz; ++i) {
    zz[i] = z[i];
    if (zz[i] > -1000.0) {
      L = first ? zz[i] : logaddexp(L, zz[i]);
      first = 0;
    }
  }
  double* allv = arc_malloc(sizeof(double) * (size_t)(na + 2));
  double* sims = arc_malloc(sizeof(double) * (size_t)(na + 1));
  double* sh = arc_malloc(sizeof(double) * (size_t)(na + 1));
  double* s = allv + 1;
  char* span = arc_nt_norm(span_text ? span_text : "");
  double ms = 0.0;
  for (int k = 0; k < na; ++k) {
    int row = allowed[k];
    sims[k] = arc_nt_sim(span, (const char* const*)r->forms[row], r->nforms[row]);
    double v = (sims[k] - 0.6) / 0.4;
    v = v < 0 ? 0 : v > 1 ? 1 : v;
    sh[k] = v * v;
    if (k == 0 || sh[k] > ms) ms = sh[k];
    s[k] = zz[2 + row] - L;
  }
  if (p->A)
    for (int k = 0; k < na; ++k) s[k] = s[k] + p->A * sh[k];
  if (p->B && feed_text && feed_text[0]) {
    char* fn = arc_nt_norm(feed_text);
    char** ft;
    int nft = split_ws(fn, &ft);
    for (int k = 0; k < na; ++k) {
      int row = allowed[k], hit = 0;
      for (int f = 0; f < r->nforms[row] && !hit; ++f) {
        char** w;
        int nw = split_ws(r->forms[row][f], &w);
        for (int j = 0; j < nw && !hit; ++j)
          if (u8len(w[j]) >= 4)
            for (int q = 0; q < nft && !hit; ++q) hit = u8len(ft[q]) >= 4 && !strcmp(ft[q], w[j]);
        arc_nt_free_strs(w, nw);
      }
      s[k] = s[k] + p->B * (hit ? 1.0 : 0.0);
    }
    arc_nt_free_strs(ft, nft);
    arc_free(fn);
  }
  if (p->T && r->ntw) {
    char* past = arc_nt_norm(past_text ? past_text : "");
    int* src = arc_calloc(sizeof(int) * (size_t)r->ntw);
    int tot = 0;
    for (int g = 0; g < r->ntw; ++g) {
      for (int f = 0; f < r->tw[g].n; ++f) src[g] += count_sub(past, r->tw[g].toks[f]);
      tot += src[g];
    }
    if (tot)
      for (int k = 0; k < na; ++k) {
        const char* grp = r->groups[allowed[k]];
        double v = 0.0;
        if (grp && grp[0]) {
          int c = 0;
          for (int g = 0; g < r->ntw; ++g)
            if (!strcmp(r->tw[g].group, grp)) c = src[g];
          v = (double)c / (double)tot;
        }
        s[k] = s[k] + p->T * v;
      }
    arc_free(src);
    arc_free(past);
  }
  if (p->R && r->rn)
    for (int k = 0; k < na; ++k) {
      int c = 0;
      for (int q = 0; q < r->rn; ++q) c += r->rr[r->rh + q] == allowed[k];
      double v = c / 2.0;
      s[k] = s[k] + p->R * (v < 1.0 ? v : 1.0);
    }
  allv[0] = (zz[0] - L) + p->bias + p->A2 * (1 - ms);
  int n = na + 1, j = 0;
  for (int k = 1; k < n; ++k)
    if (allv[k] > allv[j]) j = k;
  double mx = allv[j];
  double* pr = arc_malloc(sizeof(double) * (size_t)n);
  for (int k = 0; k < n; ++k) pr[k] = exp(allv[k] - mx);
  double sum = np_sum(pr, n);
  double conf = pr[j] / sum;
  out->pred = j == 0 ? -1 : allowed[j - 1];
  out->p = pyround(conf, 4);
  out->link = out->pred >= 0 && conf >= p->thr;
  out->sim = out->pred >= 0 ? pyround(sims[j - 1], 3) : NAN;
  if (out->link) arc_nt_rescorer_push(r, t_s, out->pred);
  arc_free(pr);
  arc_free(span);
  arc_free(zz);
  arc_free(allv);
  arc_free(sims);
  arc_free(sh);
  return 0;
}

/* ------------------------------------------------------------------ a string -> int map (insertion order kept) */
typedef struct {
  char** k;
  int* v;
  int n, cap;
  int* slot;   /* open addressing over 2^b slots, -1 empty */
  int nslot;
} smap;

static uint32_t shash(const char* s) {
  uint32_t h = 2166136261u;
  for (; *s; ++s) h = (h ^ (unsigned char)*s) * 16777619u;
  return h;
}
static int smap_find(const smap* m, const char* k) {
  if (!m->nslot) return -1;
  for (uint32_t h = shash(k) & (uint32_t)(m->nslot - 1);; h = (h + 1) & (uint32_t)(m->nslot - 1)) {
    int i = m->slot[h];
    if (i < 0) return -1;
    if (!strcmp(m->k[i], k)) return i;
  }
}
static void smap_rehash(smap* m, int nslot) {
  arc_free(m->slot);
  m->nslot = nslot;
  m->slot = arc_malloc(sizeof(int) * (size_t)nslot);
  for (int i = 0; i < nslot; ++i) m->slot[i] = -1;
  for (int i = 0; i < m->n; ++i) {
    uint32_t h = shash(m->k[i]) & (uint32_t)(nslot - 1);
    while (m->slot[h] >= 0) h = (h + 1) & (uint32_t)(nslot - 1);
    m->slot[h] = i;
  }
}
/* setdefault: returns the index of k */
static int smap_add(smap* m, const char* k, int v) {
  int i = smap_find(m, k);
  if (i >= 0) return i;
  if (m->n == m->cap) {
    int c = m->cap ? m->cap * 2 : 16;
    char** nk = arc_malloc(sizeof(char*) * (size_t)c);
    int* nv = arc_malloc(sizeof(int) * (size_t)c);
    if (m->n) {
      memcpy(nk, m->k, sizeof(char*) * (size_t)m->n);
      memcpy(nv, m->v, sizeof(int) * (size_t)m->n);
    }
    arc_free(m->k);
    arc_free(m->v);
    m->k = nk;
    m->v = nv;
    m->cap = c;
  }
  m->k[m->n] = arc_strdup(k);
  m->v[m->n++] = v;
  if (m->n * 2 > m->nslot) smap_rehash(m, m->nslot ? m->nslot * 2 : 32);
  else {
    uint32_t h = shash(k) & (uint32_t)(m->nslot - 1);
    while (m->slot[h] >= 0) h = (h + 1) & (uint32_t)(m->nslot - 1);
    m->slot[h] = m->n - 1;
  }
  return m->n - 1;
}
static void smap_free(smap* m) {
  for (int i = 0; i < m->n; ++i) arc_free(m->k[i]);
  arc_free(m->k);
  arc_free(m->v);
  arc_free(m->slot);
}

/* ------------------------------------------------------------------ textlayer.ExactNames */

struct arc_nt_exact {
  int n, maxn;
  smap full, uniq;
  char** kind;
};

arc_nt_exact* arc_nt_exact_new(const arc_kbent* kb, int n) {
  arc_nt_exact* e = arc_calloc(sizeof *e);
  e->n = n;
  e->kind = arc_calloc(sizeof(char*) * (size_t)(n + 1));
  for (int r = 0; r < n; ++r) {
    e->kind[r] = arc_strdup(kb[r].kind ? kb[r].kind : "other");
    for (int a = -1; a < kb[r].n_aliases; ++a) {
      char* k = arc_nt_snorm(a < 0 ? (kb[r].name ? kb[r].name : "") : kb[r].aliases[a]);
      if (k[0]) smap_add(&e->full, k, r);
      arc_free(k);
    }
  }
  smap sur = {0};   /* surname -> its row; -2 when several rows have it */
  for (int r = 0; r < n; ++r) {
    char* k = arc_nt_snorm(kb[r].name ? kb[r].name : "");
    char** w;
    int nw = split_ws(k, &w);
    if (nw >= 2 && u8len(w[nw - 1]) >= 3) {
      int i = smap_find(&sur, w[nw - 1]);
      if (i < 0) smap_add(&sur, w[nw - 1], r);
      else if (sur.v[i] != r) sur.v[i] = -2;
    }
    arc_nt_free_strs(w, nw);
    arc_free(k);
  }
  for (int i = 0; i < sur.n; ++i)
    if (sur.v[i] >= 0 && smap_find(&e->full, sur.k[i]) < 0) smap_add(&e->uniq, sur.k[i], sur.v[i]);
  smap_free(&sur);
  e->maxn = 1;
  for (int i = 0; i < e->full.n; ++i) {
    char** w;
    int nw = split_ws(e->full.k[i], &w);
    if (nw > e->maxn) e->maxn = nw;
    arc_nt_free_strs(w, nw);
  }
  return e;
}

void arc_nt_exact_free(arc_nt_exact* e) {
  if (!e) return;
  smap_free(&e->full);
  smap_free(&e->uniq);
  arc_nt_free_strs(e->kind, e->n);
  arc_free(e);
}

int arc_nt_exact_empty(const arc_nt_exact* e) { return !e || e->full.n == 0; }

static int cmp_int(const void* a, const void* b) { return *(const int*)a - *(const int*)b; }

int arc_nt_exact_rows_in(const arc_nt_exact* e, const char* text, int* rows) {
  char* t = arc_nt_snorm(text);
  sbuf s = {0};
  sb_putc(&s, ' ');
  sb_puts(&s, t);
  sb_putc(&s, ' ');
  arc_free(t);
  int n = 0;
  for (int i = 0; i < e->full.n; ++i) {
    sbuf k = {0};
    sb_putc(&k, ' ');
    sb_puts(&k, e->full.k[i]);
    sb_putc(&k, ' ');
    if (strstr(s.s, k.s)) {
      int r = e->full.v[i], dup = 0;
      for (int q = 0; q < n && !dup; ++q) dup = rows[q] == r;
      if (!dup) rows[n++] = r;
    }
    arc_free(k.s);
  }
  arc_free(s.s);
  qsort(rows, (size_t)n, sizeof(int), cmp_int);
  return n;
}

static int cmp_xspan(const void* x, const void* y) {
  const arc_nt_xspan *a = x, *b = y;
  if (a->i != b->i) return a->i - b->i;
  if (a->j != b->j) return a->j - b->j;
  return a->row - b->row;
}

int arc_nt_exact_spans(const arc_nt_exact* e, const char* const* texts, int nw, const unsigned char* used,
                       arc_nt_xspan* out) {
  char** tk = arc_malloc(sizeof(char*) * (size_t)(nw + 1));
  unsigned char* u = arc_calloc((size_t)nw + 1);
  for (int i = 0; i < nw; ++i) {
    tk[i] = arc_nt_snorm(texts[i]);
    if (used) u[i] = used[i];
  }
  int no = 0, top = e->maxn < 4 ? e->maxn : 4;
  for (int n = top; n >= 1; --n)
    for (int i = 0; i + n <= nw; ++i) {
      int bad = 0;
      for (int k = i; k < i + n; ++k) bad |= u[k];
      if (bad || !tk[i][0] || !tk[i + n - 1][0]) continue;
      sbuf s = {0};
      for (int k = i; k < i + n; ++k)
        if (tk[k][0]) {
          if (s.n) sb_putc(&s, ' ');
          sb_puts(&s, tk[k]);
        }
      if (!s.n) continue;
      int ix = smap_find(&e->full, s.s), r = ix >= 0 ? e->full.v[ix] : -1;
      if (r < 0 && n == 1) {
        ix = smap_find(&e->uniq, s.s);
        r = ix >= 0 ? e->uniq.v[ix] : -1;
      }
      arc_free(s.s);
      if (r < 0) continue;
      if (n == 1 && !arc_nt_is_cap(texts[i])) continue;
      for (int k = i; k < i + n; ++k) u[k] = 1;
      out[no].i = i;
      out[no].j = i + n;
      out[no++].row = r;
    }
  qsort(out, (size_t)no, sizeof *out, cmp_xspan);
  arc_nt_free_strs(tk, nw);
  arc_free(u);
  return no;
}

const char* arc_nt_exact_tag_of(const arc_nt_exact* e, int row) {
  static const char* K[][2] = {{"person", "entity.mention.person"},
                               {"team", "entity.mention.team"},
                               {"organization", "entity.mention.organization"},
                               {"place", "entity.mention.place"},
                               {"work_product", "entity.mention.work_product"},
                               {"event_name", "entity.mention.event_name"},
                               {"legal_ref", "entity.mention.legal_ref"},
                               {"game_entity", "entity.mention.game_entity"},
                               {"game_map", "entity.mention.game_map"}};
  const char* k = row >= 0 && row < e->n ? e->kind[row] : "";
  for (size_t i = 0; i < sizeof K / sizeof K[0]; ++i)
    if (!strcmp(k, K[i][0])) return K[i][1];
  return "entity.mention.person";
}

/* ------------------------------------------------------------------ kbsnap */

typedef struct {
  int row;
  char *fn, *fm;
} snap_form;

struct arc_nt_kbsnap {
  snap_form* F;
  int nf;
  char** kind;
  int n;
};

static int is_suffix(const char* p) {   /* p.lower().strip('.') in (jr, sr, ii, iii, iv) */
  char b[16];
  size_t L = strlen(p);
  if (L >= sizeof b) return 0;
  size_t a = 0, e = L;
  while (a < e && p[a] == '.') a++;
  while (e > a && p[e - 1] == '.') e--;
  size_t n = 0;
  for (size_t i = a; i < e; ++i) b[n++] = (char)tolower((unsigned char)p[i]);
  b[n] = 0;
  return !strcmp(b, "jr") || !strcmp(b, "sr") || !strcmp(b, "ii") || !strcmp(b, "iii") || !strcmp(b, "iv");
}

arc_nt_kbsnap* arc_nt_kbsnap_new(const arc_kbent* kb, int n) {
  arc_nt_kbsnap* k = arc_calloc(sizeof *k);
  k->n = n;
  k->kind = arc_calloc(sizeof(char*) * (size_t)(n + 1));
  int cap = 16;
  k->F = arc_malloc(sizeof(snap_form) * (size_t)cap);
  for (int r = 0; r < n; ++r) {
    k->kind[r] = arc_strdup(kb[r].kind ? kb[r].kind : "other");
    char* nm = join_ws(kb[r].name ? kb[r].name : "");
    if (!nm[0]) {
      arc_free(nm);
      continue;
    }
    /* forms = {n} + last part (not a suffix) + aliases, in that order */
    char** forms = arc_malloc(sizeof(char*) * (size_t)(kb[r].n_aliases + 2));
    int nfm = 0;
    forms[nfm++] = arc_strdup(nm);
    char** w;
    int nw = split_ws(nm, &w), np = 0, last = -1;
    for (int i = 0; i < nw; ++i)
      if (!is_suffix(w[i])) {
        np++;
        last = i;
      }
    if (np > 1) forms[nfm++] = arc_strdup(w[last]);
    arc_nt_free_strs(w, nw);
    for (int a = 0; a < kb[r].n_aliases; ++a) {
      char* f = join_ws(kb[r].aliases[a]);
      if (f[0]) forms[nfm++] = f;
      else arc_free(f);
    }
    for (int i = 0; i < nfm; ++i) {
      int dup = 0;
      for (int q = 0; q < i && !dup; ++q) dup = !strcmp(forms[q], forms[i]);
      char* fn = dup ? NULL : arc_nt_nrm(forms[i]);
      if (fn && fn[0]) {
        if (k->nf == cap) {
          snap_form* nf = arc_malloc(sizeof(snap_form) * (size_t)cap * 2);
          memcpy(nf, k->F, sizeof(snap_form) * (size_t)k->nf);
          arc_free(k->F);
          k->F = nf;
          cap *= 2;
        }
        k->F[k->nf].row = r;
        k->F[k->nf].fn = fn;
        k->F[k->nf++].fm = arc_nt_kbmeta(fn);
      } else arc_free(fn);
    }
    arc_nt_free_strs(forms, nfm);
    arc_free(nm);
  }
  return k;
}

void arc_nt_kbsnap_free(arc_nt_kbsnap* k) {
  if (!k) return;
  for (int i = 0; i < k->nf; ++i) {
    arc_free(k->F[i].fn);
    arc_free(k->F[i].fm);
  }
  arc_free(k->F);
  arc_nt_free_strs(k->kind, k->n);
  arc_free(k);
}

int arc_nt_kbsnap_empty(const arc_nt_kbsnap* k) { return !k || k->nf == 0; }

double arc_nt_kbsnap_score(const arc_nt_kbsnap* k, const char* text, int* row, int* ph) {
  *row = -1;
  *ph = 0;
  char* t = arc_nt_nrm(text);
  if (!t[0]) {
    arc_free(t);
    return 0.0;
  }
  char* mt = arc_nt_kbmeta(t);
  double best = 0.0;
  for (int i = 0; i < k->nf; ++i) {
    double sc = arc_nt_seqratio(t, k->F[i].fn);
    int p = mt[0] && !strcmp(mt, k->F[i].fm);
    double s2 = sc > (p ? 0.9 : 0.0) ? sc : (p ? 0.9 : 0.0);
    if (s2 > best) {
      best = s2;
      *row = k->F[i].row;
      *ph = p;
    }
  }
  arc_free(t);
  arc_free(mt);
  return best;
}

int arc_nt_kbsnap_link(const arc_nt_kbsnap* k, const char* heard, int* row, double* score) {
  *row = -1;
  *score = 0;
  if (arc_nt_kbsnap_empty(k)) return 0;
  int r, ph;
  double sc = arc_nt_kbsnap_score(k, heard ? heard : "", &r, &ph);
  if (sc >= 0.85 && r >= 0) {
    *row = r;
    *score = pyround(sc, 3);
    return 1;
  }
  return 0;
}

static const char* snap_tag(const char* kind) {
  if (!strcmp(kind, "team")) return "entity.mention.team";
  if (!strcmp(kind, "organization") || !strcmp(kind, "org")) return "entity.mention.organization";
  if (!strcmp(kind, "place")) return "entity.mention.place";
  return "entity.mention.person";
}

int arc_nt_add_spans(const arc_nt_kbsnap* k, const arc_nt_word* words, int nw, const double (*taken)[2], int n_taken,
                     arc_nt_snap_span** out) {
  *out = NULL;
  if (arc_nt_kbsnap_empty(k) || nw <= 0) return 0;
  int* W = arc_malloc(sizeof(int) * (size_t)nw);
  int n = 0;
  for (int i = 0; i < nw; ++i)
    if (words[i].text && words[i].text[0]) W[n++] = i;
  unsigned char* used = arc_calloc((size_t)n + 1);
  for (int i = 0; i < n; ++i) used[i] = words[W[i]].tag && !strncmp(words[W[i]].tag, "ENTITY_", 7);
  int ntk = n_taken, captk = n_taken + n + 1;
  double(*tk)[2] = arc_malloc(sizeof(double[2]) * (size_t)captk);
  if (n_taken) memcpy(tk, taken, sizeof(double[2]) * (size_t)n_taken);
  int no = 0;
  arc_nt_snap_span* o = arc_calloc(sizeof *o * (size_t)(n + 1));
  for (int len = 3; len >= 1; --len)
    for (int i = 0; i + len <= n; ++i) {
      int bad = 0;
      for (int q = i; q < i + len; ++q) bad |= used[q];
      if (bad) continue;
      double s = words[W[i]].start, e = words[W[i + len - 1]].end;
      for (int q = 0; q < ntk && !bad; ++q) bad = tk[q][0] < e && s < tk[q][1];
      if (bad) continue;
      sbuf t = {0};
      int cap = 0;
      for (int q = i; q < i + len; ++q) {
        if (q > i) sb_putc(&t, ' ');
        sb_puts(&t, words[W[q]].text);
        cap |= arc_nt_isupper0(words[W[q]].text);
      }
      char* nt = arc_nt_nrm(t.s);
      int short_ = (int)strlen(nt) < 4;
      arc_free(nt);
      if (!cap || short_) {
        arc_free(t.s);
        continue;
      }
      int row, ph;
      double sc = arc_nt_kbsnap_score(k, t.s, &row, &ph);
      if (sc >= 0.92 && (ph || sc >= 0.97) && row >= 0) {
        arc_nt_snap_span* r = &o[no++];
        r->start = pyround(s, 3);
        r->end = pyround(e, 3);
        r->n_words = len;
        for (int q = 0; q < len; ++q) r->w[q] = W[i + q];
        r->heard = t.s;
        r->row = row;
        r->tag = snap_tag(k->kind[row]);
        r->snap_score = pyround(sc, 3);
        for (int q = i; q < i + len; ++q) used[q] = 1;
        tk[ntk][0] = s;
        tk[ntk++][1] = e;
      } else arc_free(t.s);
    }
  arc_free(W);
  arc_free(used);
  arc_free(tk);
  *out = o;
  return no;
}

void arc_nt_snap_spans_free(arc_nt_snap_span* s, int n) {
  if (!s) return;
  for (int i = 0; i < n; ++i) arc_free(s[i].heard);
  arc_free(s);
}
